import pytest
from jsonschema import validate
import os

# Test for /pet/findByStatus endpoint

@pytest.mark.parametrize(
    "status, expected_status_code",
    [
        ("available", 200),  # Valid status
        ("sold", 200),       # Valid status
        ("pending", 200),    # Valid status
        ("invalid", 400),    # Invalid status
        ("", 400),           # Missing status
    ]
)
def test_find_pets_by_status(api_client, schema_validator, status, expected_status_code, valid_api_key):
    """
    Test the /pet/findByStatus endpoint with different status values and validate response status codes.
    """
    headers = {"Authorization": f"Bearer {valid_api_key}"}
    params = {"status": status}
    
    response = api_client.get("/pet/findByStatus", headers=headers, params=params)

    assert response.status_code == expected_status_code, f"Unexpected status code: {response.status_code}"
    
    if response.status_code == 200:
        pets = response.json()
        assert isinstance(pets, list), "Response should be a list of pets."
        for pet in pets:
            assert schema_validator.validate_pet(pet), f"Invalid pet schema: {pet}"
    elif response.status_code == 400:
        error_message = response.json().get("message", "")
        assert error_message == "Invalid status value", f"Unexpected error message: {error_message}"

